mapper.select:
SELECT a.*, u.real_name as publisher_name, d.dept_name, d.dept_code, (SELECT COUNT(*) FROM sys_announcement_read ar WHERE ar.announcement_id = a.id) as read_count, (SELECT COUNT(*) FROM sys_user WHERE user_type IN (3,4) AND status = 1) - (SELECT COUNT(*) FROM sys_announcement_read ar WHERE ar.announcement_id = a.id) as unread_count FROM sys_announcement a LEFT JOIN sys_user u ON a.publisher_id = u.id LEFT JOIN sys_department d ON a.dept_id = d.id WHERE a.status = 1
AND a.title LIKE CONCAT('%', #{title}, '%')
AND a.announcement_type = #{announcementType}
AND a.dept_id = #{deptId}
AND a.scope = #{scope}
AND a.publish_time >= #{startTime}
AND a.publish_time <= #{endTime}
ORDER BY a.is_top DESC, a.top_order ASC, a.publish_time DESC

SELECT a.*, u.real_name as publisher_name, d.dept_name, d.dept_code FROM sys_announcement a LEFT JOIN sys_user u ON a.publisher_id = u.id LEFT JOIN sys_department d ON a.dept_id = d.id WHERE a.status = 1 AND a.scope = #{scope}
AND a.dept_id = #{deptId}
ORDER BY a.is_top DESC, a.top_order ASC, a.publish_time DESC

SELECT a.*, u.real_name as publisher_name, d.dept_name, d.dept_code FROM sys_announcement a LEFT JOIN sys_user u ON a.publisher_id = u.id LEFT JOIN sys_department d ON a.dept_id = d.id WHERE a.status = 1 AND a.is_top = 1 AND a.scope = #{scope}
AND a.dept_id = #{deptId}
ORDER BY a.top_order ASC LIMIT #{limit}

