UPDATE sys_announcement
title = #{title}, content = #{content}, announcement_type = #{announcementType}, scope = #{scope}, dept_id = #{deptId}, deadline = #{deadline}, is_top = #{isTop}, top_order = #{topOrder},
WHERE id = #{id}

UPDATE sys_announcement
SET is_top = #{isTop}, top_order = #{topOrder}
WHERE id = #{id}

